// Script para simular transmisión de patrullas BB200XX y CC300ZZ
const admin = require('firebase-admin');

const serviceAccount = require('./serviceAccountKey.json');

admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: "https://seguridad-mdp-v2-default-rtdb.firebaseio.com"
});

const db = admin.database();

// Crear una imagen simple en base64 (rectángulo de color)
function crearFrameBase64(color, texto) {
  // Imagen PNG simple 120x80 con color sólido
  // Este es un data URL de una imagen generada
  const colores = {
    'azul': 'data:image/jpeg;base64,',
    'verde': 'data:image/jpeg;base64,',
    'rojo': 'data:image/jpeg;base64,'
  };
  return colores[color] || colores['azul'];
}

const patrullas = [
  { id: 'BB200XX', color: 'azul' },
  { id: 'CC300ZZ', color: 'verde' }
];

let frameCount = 0;
const DURACION_SEGUNDOS = 60;
const INTERVALO_MS = 200; // 5 fps

console.log('🎬 Iniciando simulación de patrullas...');
console.log(`📡 Patrullas: ${patrullas.map(p => p.id).join(', ')}`);
console.log(`⏱️  Duración: ${DURACION_SEGUNDOS} segundos`);
console.log('');
console.log('👉 Ahora abrí el COM y hacé clic en una patrulla para ver las miniaturas');
console.log('');

const intervalo = setInterval(async () => {
  frameCount++;
  
  for (const patrulla of patrullas) {
    try {
      await db.ref(`frames/${patrulla.id}/latest`).set({
        data: crearFrameBase64(patrulla.color),
        timestamp: Date.now()
      });
    } catch (err) {
      console.error(`❌ Error enviando frame a ${patrulla.id}:`, err.message);
    }
  }
  
  if (frameCount % 25 === 0) {
    const segundosRestantes = DURACION_SEGUNDOS - (frameCount * INTERVALO_MS / 1000);
    console.log(`📸 Frame ${frameCount} enviado - ${Math.round(segundosRestantes)}s restantes`);
  }
  
}, INTERVALO_MS);

// Detener después de la duración
setTimeout(() => {
  clearInterval(intervalo);
  console.log('');
  console.log('✅ Simulación terminada');
  console.log('🧹 Las miniaturas desaparecerán en 30 segundos');
  process.exit(0);
}, DURACION_SEGUNDOS * 1000);
